CREATE SEQUENCE public.creator_number_seq;
ALTER TABLE public.creator_registrations ADD COLUMN creator_number integer UNIQUE, ADD COLUMN public_id text UNIQUE, ADD COLUMN avatar_url text, ADD COLUMN is_visible boolean NOT NULL DEFAULT true;
UPDATE public.creator_registrations SET creator_number=nextval('public.creator_number_seq') WHERE creator_number IS NULL;
UPDATE public.creator_registrations SET public_id='JV-' || lpad(creator_number::text, greatest(4,length(creator_number::text)), '0');
CREATE TABLE public.public_creators (public_id text PRIMARY KEY, creator_number integer UNIQUE NOT NULL, full_name text NOT NULL, city_country text, primary_speciality text, ai_tools text[] NOT NULL DEFAULT '{}', experience_level text, portfolio_link text, avatar_url text, created_at timestamptz NOT NULL DEFAULT now(), is_visible boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.public_creators TO anon, authenticated;
GRANT ALL ON public.public_creators TO service_role;
ALTER TABLE public.public_creators ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Visible creator profiles are public" ON public.public_creators FOR SELECT TO anon,authenticated USING (is_visible);
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('admin')), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own role" ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.is_jv_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') $$;
REVOKE ALL ON FUNCTION public.is_jv_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_jv_admin() TO authenticated;
GRANT SELECT,UPDATE ON public.creator_registrations TO authenticated;
CREATE POLICY "Admins read registrations" ON public.creator_registrations FOR SELECT TO authenticated USING (public.is_jv_admin());
CREATE POLICY "Admins manage registrations" ON public.creator_registrations FOR UPDATE TO authenticated USING (public.is_jv_admin()) WITH CHECK (public.is_jv_admin());
CREATE FUNCTION public.assign_creator_number() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.creator_number:=nextval('public.creator_number_seq'); NEW.public_id:='JV-' || lpad(NEW.creator_number::text,greatest(4,length(NEW.creator_number::text)),'0'); NEW.is_visible:=true; RETURN NEW; END $$;
CREATE TRIGGER assign_creator_number BEFORE INSERT ON public.creator_registrations FOR EACH ROW EXECUTE FUNCTION public.assign_creator_number();
CREATE FUNCTION public.sync_public_creator() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.public_creators(public_id,creator_number,full_name,city_country,primary_speciality,ai_tools,experience_level,portfolio_link,avatar_url,created_at,is_visible) VALUES(NEW.public_id,NEW.creator_number,NEW.full_name,NEW.location,NEW.speciality,coalesce(NEW.tools,'{}'),NEW.experience,NEW.portfolio_url,NEW.avatar_url,NEW.created_at,NEW.is_visible) ON CONFLICT(public_id) DO UPDATE SET full_name=EXCLUDED.full_name,city_country=EXCLUDED.city_country,primary_speciality=EXCLUDED.primary_speciality,ai_tools=EXCLUDED.ai_tools,experience_level=EXCLUDED.experience_level,portfolio_link=EXCLUDED.portfolio_link,avatar_url=EXCLUDED.avatar_url,is_visible=EXCLUDED.is_visible; RETURN NEW; END $$;
CREATE TRIGGER sync_public_creator AFTER INSERT OR UPDATE ON public.creator_registrations FOR EACH ROW EXECUTE FUNCTION public.sync_public_creator();
INSERT INTO public.public_creators SELECT public_id,creator_number,full_name,location,speciality,coalesce(tools,'{}'),experience,portfolio_url,avatar_url,created_at,is_visible FROM public.creator_registrations;
CREATE FUNCTION public.creator_launch_id(launch_code text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public_id FROM public.creator_registrations WHERE mission_code=launch_code AND is_visible LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.creator_launch_id(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.creator_launch_id(text) TO anon,authenticated;
CREATE TABLE public.hire_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_public_id text NOT NULL REFERENCES public.public_creators(public_id), brand_name text NOT NULL CHECK(length(trim(brand_name)) BETWEEN 1 AND 200), contact_person text NOT NULL CHECK(length(trim(contact_person)) BETWEEN 1 AND 200), business_email text NOT NULL CHECK(length(business_email) BETWEEN 3 AND 200), phone text NOT NULL CHECK(length(phone) BETWEEN 5 AND 40), project_details text NOT NULL CHECK(length(trim(project_details)) BETWEEN 1 AND 5000), budget text NOT NULL CHECK(length(budget) BETWEEN 1 AND 200), created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.hire_requests TO anon,authenticated;
GRANT SELECT ON public.hire_requests TO authenticated;
GRANT ALL ON public.hire_requests TO service_role;
ALTER TABLE public.hire_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Brands submit hiring enquiry" ON public.hire_requests FOR INSERT TO anon,authenticated WITH CHECK (EXISTS(SELECT 1 FROM public.public_creators c WHERE c.public_id=creator_public_id AND c.is_visible));
CREATE POLICY "Admins read hiring enquiries" ON public.hire_requests FOR SELECT TO authenticated USING (public.is_jv_admin());
CREATE POLICY "Upload creator photos" ON storage.objects FOR INSERT TO anon,authenticated WITH CHECK (bucket_id='creator-avatars' AND lower(storage.extension(name)) IN ('png','jpg','jpeg','webp'));
ALTER PUBLICATION supabase_realtime ADD TABLE public.public_creators;